from lib import *
S = SS('g30')
steps = [
    step("三种变量类型都能嵌入单个文件 hello.txt:string 与 []byte 得到 \"hello, embed\",embed.FS 用 ReadFile 读到同样的内容。目录规则://go:embed assets 只嵌入 3 个文件(assets/a.txt、assets/b.txt、assets/sub/c.md)——名字以 . 或 _ 开头的文件被排除;//go:embed all:assets 嵌入 7 个文件(包括 .hidden、_under.txt、sub/.secret、sub/_x.md);通配 assets/*.txt assets/sub/*.md 嵌入 5 个文件(通配符匹配到的 _ 开头文件会包含进来)。", t=tl(S(1)), done=lidx(S(1), 'string 变量', '//go:embed assets  '), mark=lidx(S(1), 'all:assets', 'assets/*.txt'), kv=KV([['//go:embed assets', '3 个文件:跳过 . 与 _ 开头的'], ['//go:embed all:assets', '7 个文件:全部'], ['//go:embed assets/*.txt assets/sub/*.md', '5 个文件:通配符匹配到的 _ 开头文件也会包含'], ['string / []byte / embed.FS', '单个文件三种都行']], ['//go:embed all:assets'])),
    step("embed.FS 里的文件:ReadDir(\"assets\") 的顺序是 a.txt、b.txt、sub(按名字排序);Stat 得到 Size = 7、Mode = -r--r--r--、ModTime.IsZero() = true;读不存在的文件:open assets/不存在.txt: file does not exist;路径带前导斜杠也是 file does not exist;fs.Sub(dirFS, \"assets\") 之后读 sub/c.md 得到 \"# c\\n\";修改 []byte 变量(helloBytes[0] = 'J')得到 \"Jello, embed\",再从 embed.FS 读仍是 \"hello, embed\"。", t=tl(S(2)), done=lidx(S(2), 'ReadDir', 'Stat(assets/a.txt)'), mark=lidx(S(2), '路径带前导斜杠', 'fs.Sub', '修改 []byte 变量'), kv=KV([['ReadDir', '按名字排序'], ['Stat', 'Mode -r--r--r--,ModTime 为零'], ['路径', '不能有前导斜杠'], ['[]byte 变量', '可以修改,不影响 embed.FS 里的内容']], ['[]byte 变量'])),
    step("配合 net/http:http.FileServer(http.FS(sub)):GET /a.txt → 200,Content-Type text/plain; charset=utf-8,Content-Length 7,没有 Last-Modified;GET /sub/c.md → 200,Content-Length 4;GET /missing → 404 page not found;GET / → 200,text/html 的目录列表。embed.FS 的修改时间为零,所以响应里没有 Last-Modified。", t=tl(S(3)), done=lidx(S(3), 'GET /a.txt', 'GET /sub/c.md'), mark=lidx(S(3), 'GET /missing', 'GET /  '), kv=KV([['GET /a.txt', '200,text/plain,没有 Last-Modified'], ['GET /missing', '404'], ['GET /', '200,目录列表(text/html)'], ['原因', 'ModTime 为零 → 不发 Last-Modified']], ['原因'])),
    step("读取成本(7 轮取中位数):使用 string 变量 1.92 ns/op、0 次分配;embed.FS.ReadFile 57.48 ns/op,fs.ReadFile(dirFS, \"assets/a.txt\")86.50 ns/op,都是 2 次分配(拷贝内容);Open + Stat + Close 70.56 ns/op。要频繁使用就直接嵌成 string,不要每次 ReadFile。", t=tl(S(4)), done=lidx(S(4), '使用 string 变量'), mark=lidx(S(4), 'embed.FS.ReadFile', 'fs.ReadFile', 'AllocsPerRun'), b=bars([['string 变量', 1.92, '1.92'], ['embed.FS.ReadFile', 57.48, '57.48'], ['Open+Stat+Close', 70.56, '70.56'], ['fs.ReadFile(dirFS)', 86.50, '86.50']], 86.50, done=[0], mark=[1, 2, 3]), kv=KV([['string 变量', '1.92 ns,0 次分配'], ['embed.FS.ReadFile', '57.48 ns,2 次分配'], ['fs.ReadFile(dirFS, …)', '86.50 ns']], ['embed.FS.ReadFile'])),
    step("二进制里:不嵌入的同类程序 2429698 字节;嵌入 1 MiB 随机文件、同时用 []byte 与 string 各声明一次,变成 4543330 字节,增加 2113632 字节(约 2.02 MiB)。go tool nm -size 里 ≥ 1 MiB 的符号:R go:string.*(1085352 字节,只读段,放 string)与 D main..gobytes.1(1048576 字节,数据段,放 []byte)。两种声明各占一份,没有合并。", t=tl(S(5)), done=lidx(S(5), '不嵌入的同类程序', 'go tool nm -size'), mark=lidx(S(5), 'go:string', 'gobytes', '各占一份'), b=bars([['不嵌入(MiB)', 2.32, '2.32'], ['嵌入 1 MiB 两次声明(MiB)', 4.33, '4.33']], 4.33, done=[0], mark=[1]), kv=KV([['不嵌入', '2429698 字节'], ['嵌入并声明 []byte 与 string', '4543330 字节(+2.02 MiB)'], ['string 的数据', '只读段 R go:string.*'], ['[]byte 的数据', '数据段 D main..gobytes.1']], ['嵌入并声明 []byte 与 string'])),
    step("写错时编译器的报错:匹配不到文件:pattern nothing.txt: no matching files found;写到模块之外:pattern ../a.txt: invalid pattern syntax;在函数里声明:go:embed cannot apply to var inside func;变量类型是 int:go:embed cannot apply to var of type int;没有导入 embed 包:go:embed requires import \"embed\" (or import _ \"embed\", if package is not used);把含两个文件的目录嵌进 string:invalid go:embed: multiple files for type string;而只含 1 个文件(\"xx\")的目录嵌进 string 能编译,运行得到 len = 2、内容 xx。", t=tl(S(6)), mark=lidx(S(6), 'no matching files found', 'invalid pattern syntax', 'inside func', 'type int', 'requires import', 'multiple files for type string', '只含 1 个文件'), kv=KV([['不存在的文件', 'no matching files found'], ['../ 路径', 'invalid pattern syntax'], ['函数里 / 类型不对', 'cannot apply to var …'], ['目录嵌进 string', '多个文件:multiple files for type string;只有 1 个文件时可以']], ['目录嵌进 string'])),
]
A = mkartg('g30', 30, 'Go,embed,go:embed,fs.FS,静态资源,真实验证,动画演示',
    '在 Go 1.27.1 里验证 go:embed:string、[]byte、embed.FS 三种变量;目录嵌入默认跳过 . 与 _ 开头的文件,all: 前缀才包含;embed.FS 只读、按名字排序、修改时间为零(http.FS 因此没有 Last-Modified);ReadFile 拷贝内容(2 次分配,57 ns),string 变量零成本;嵌入的数据在可执行文件里:[]byte 在数据段、string 在只读段,各占一份(1 MiB 文件两种声明共增加 2.02 MiB);各种写错时的编译错误。',
    'go:embed 让二进制自带静态资源,不用再带一个 assets 目录部署。这篇逐项验证它的规则:怎么写、哪些文件被嵌进去、embed.FS 里的文件长什么样、配合 net/http 的表现、读取成本,以及数据在二进制里的位置与体积,最后列出常见的编译错误。',
    [('3 / 7 / 5', '同一个 assets 目录,三种写法嵌入的文件数:默认 3 个,all: 前缀 7 个,通配符 5 个'), ('2.02 MiB', '嵌入 1 MiB 文件,同时声明 []byte 与 string 时二进制增加的大小'), ('57.48 ns', 'embed.FS.ReadFile 的耗时(2 次分配);string 变量是 1.92 ns')],
    [('三种变量与目录规则', '<p>单个文件可以嵌到 <code>string</code>、<code>[]byte</code> 或 <code>embed.FS</code>;目录或多个文件只能嵌到 <code>embed.FS</code>。目录模式默认排除以 <code>.</code> 或 <code>_</code> 开头的文件(防止把 <code>.env</code> 一类文件打进去),要包含就加 <code>all:</code> 前缀;通配符匹配到的文件不受这条限制。</p>'),
     ('embed.FS 里的文件', '<p>它实现了 <code>fs.FS</code>(并有 <code>ReadFile</code>、<code>ReadDir</code>),文件只读(<code>-r--r--r--</code>)、按名字排序、修改时间为零值。路径用不带前导斜杠的 <code>/</code> 分隔形式。<code>[]byte</code> 变量是数据段里的副本,可以修改,但不影响 <code>embed.FS</code> 里的内容。</p>'),
     ('配合 http.FS', '<p><code>http.FS</code> 把 <code>fs.FS</code> 变成 <code>http.FileSystem</code>,静态文件服务一行搞定。因为修改时间是零值,响应没有 <code>Last-Modified</code>,浏览器就不会做基于时间的条件请求;要缓存控制得自己加 <code>Cache-Control</code>/<code>ETag</code>(本文没有试)。</p>'),
     ('读取成本', '<p><code>ReadFile</code> 要把内容拷贝到新分配的切片里(2 次分配),约 57 ns;直接用 <code>string</code> 变量没有任何运行时成本。内容很小但读得很频繁时,优先嵌成 <code>string</code>。</p>'),
     ('在二进制里', '<p>嵌入的内容就是二进制的一部分:体积直接增加文件大小。实验里同一个文件声明了 <code>[]byte</code> 与 <code>string</code> 两次,符号表里就有两份 1 MiB 的数据(只读段的 <code>go:string.*</code> 与数据段的 <code>main..gobytes.1</code>),所以不要为同一个文件重复声明。</p>'),
     ('编译错误', '<p>写错的信息都很直接。有一个容易忽略的特例:把一个<b>只含一个文件</b>的目录嵌进 <code>string</code> 是允许的(得到那个文件的内容),文件变成两个就报错,所以对目录用 <code>embed.FS</code> 更不容易出意外。</p>')],
    steps,
    [ENV_G + '。所有输出来自真实运行;http 部分用 httptest 直接调用 handler;体积数字来自 go build 的默认选项;符号来自 go tool nm -size',
     '没有验证:嵌入符号链接与其它特殊文件的规则、go:embed 对构建缓存与增量编译的影响、与 //go:generate 配合生成资源的流程、大文件(几百 MiB)对链接时间与内存的影响、压缩后嵌入(如 gzip)的做法'],
    'go:embed')
